'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import MediaStudio from './MediaStudio';
import { personalHref, personalView } from '../lib/personal-routes.mjs';
import {
  Activity, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, BarChart3, Bell,
  BookMarked, BookOpen, Bot, CalendarDays, Check, CheckCheck, CheckCircle2, ChevronDown,
  ChevronLeft, ChevronRight, Circle, Clock3, Compass, CreditCard, Crown, Download,
  ExternalLink, FileText, Flame, FolderOpen, GraduationCap, Heart, HelpCircle,
  Home, LayoutDashboard, Leaf, ListChecks, Loader2, LogOut, Menu, MessageCircle,
  MoreHorizontal, Plus, Puzzle, Search, Send, Settings, ShieldCheck, Smartphone,
  Sparkles, Sprout, Target, Trash2, TrendingUp, User, Users, Wallet, Wand2,
  Workflow, X, Zap, Pencil, KeyRound, LockKeyhole, AlertCircle, Rocket, Play,
  RefreshCw, Server, Receipt, Terminal, SlidersHorizontal, Save, Mail, Eye, EyeOff, Pause, Timer, Languages, Briefcase, Utensils, Coffee, ScanLine, Mic, Camera, AudioLines
} from 'lucide-react';

const NAV = [
  ['overview', '我的工作台', LayoutDashboard], ['ai', 'AI 助手', Sparkles],
  ['media', '语音与拍照', Mic], ['agents', 'Agent 工作室', Workflow], ['learning', '学习计划', BookOpen],
  ['life', '生活管理', Leaf], ['knowledge', '知识库', BookMarked],
  ['plugins', '插件市场', Puzzle], ['membership', '会员中心', Crown],
];
const VIEWS = Object.fromEntries([...NAV, ['user', '用户中心']].map(a => [a[0], a[1]]));
const ICONS = { book: BookOpen, brain: Sparkles, sparkles: Sparkles, heart: Heart, leaf: Leaf, wallet: Wallet, code: Terminal, target: Target, graduation: GraduationCap, calendar: CalendarDays, bot: Bot, search: Search, fitness: Activity, finance: Wallet, writing: Pencil, health: Heart, learning: BookOpen, life: Leaf, knowledge: BookMarked, planner: CalendarDays, research: Search, coach: Target, tutor: GraduationCap, nutrition: Heart, study: BookOpen, bookopen: BookOpen, bookmarked: BookMarked, calendardays: CalendarDays, graduationcap: GraduationCap, sprout: Sprout, timer: Timer, languages: Languages, briefcase: Briefcase, utensils: Utensils, chartnoaxescombined: BarChart3, heartpulse: Heart, listchecks: ListChecks, workflow: Workflow, lightbulb: Sparkles, activity: Activity, braincircuit: Bot, compass: Compass, coffee: Coffee, scanline: ScanLine };
const KINDS = { task: ['学习任务', ListChecks], goal: ['学习目标', Target], course: ['课程管理', GraduationCap], focus: ['专注记录', Clock3], review: ['复习笔记', RefreshCw], habit: ['习惯打卡', Flame], expense: ['收支账本', Wallet], health: ['健康记录', Activity], event: ['日程安排', CalendarDays], note: ['知识笔记', FileText] };
const EMPTY = { user: null, agents: [], plugins: [], plans: [], settings: {}, records: [], runs: [], orders: [], installed: [], conversations: [], stats: {} };
const EXAMPLE_TASKS = [{ title: '给今天留出 25 分钟的专注时间', category: '专注学习', color: 'green' }, { title: '整理一条值得留下的读书笔记', category: '知识积累', color: 'purple' }, { title: '走出去，开启一次轻松的散步', category: '健康生活', color: 'orange' }];
const currency = n => Number(n || 0).toLocaleString('zh-CN', { maximumFractionDigits: 2 });
const fmtDate = (d, time = false) => d ? new Date(d).toLocaleString('zh-CN', time ? { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' } : { year: 'numeric', month: '2-digit', day: '2-digit' }) : '—';
const dayKey = () => new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Shanghai' });
const statusName = s => ({ pending: '待处理', queued: '排队中', partial: '部分完成', not_built: '尚未构建', success: '已完成', paid: '已支付', completed: '已完成', running: '进行中', failed: '失败', cancelled: '已取消', done: '已完成', active: '进行中', waiting: '等待中', building: '构建中', ready: '已就绪' }[s] || s || '待开始');
const fileSize = n => Number(n) >= 1048576 ? `${(Number(n)/1048576).toFixed(1)} MB` : `${Math.max(1,Math.round(Number(n||0)/1024))} KB`;
const requestUUID = () => { const bytes = new Uint8Array(16); globalThis.crypto.getRandomValues(bytes); bytes[6] = (bytes[6] & 15) | 64; bytes[8] = (bytes[8] & 63) | 128; const value = Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join(''); return `${value.slice(0,8)}-${value.slice(8,12)}-${value.slice(12,16)}-${value.slice(16,20)}-${value.slice(20)}`; };
const cx = (...a) => a.filter(Boolean).join(' ');
const resolveIcon = name => ICONS[String(name || '').toLowerCase()] || Sparkles;

async function api(payload, resource) {
  const res = await fetch(resource ? `/api/app?${new URLSearchParams(resource)}` : '/api/app', payload ? { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) } : { cache: 'no-store' });
  let json;
  try { json = await res.json(); } catch { throw new Error('服务暂时无法连接，请稍后重试。'); }
  if (!res.ok || json.error) { const error = new Error(json.error || '请求未成功，请重试。'); error.status = res.status; throw error; }
  return json;
}

function Button({ children, className = '', variant = 'primary', loading, icon: Icon, ...props }) {
  return <button className={cx('btn', `btn-${variant}`, className)} {...props} disabled={props.disabled || loading}>{loading ? <Loader2 size={16} className="spin" /> : Icon ? <Icon size={16} /> : null}{children}</button>;
}
function IconButton({ icon: Icon, label, ...props }) { return <button className="icon-button" aria-label={label} title={label} {...props}><Icon size={18} /></button>; }
function Avatar({ icon, color, size = '', children }) { const Icon = resolveIcon(icon); const custom=/^#[0-9a-f]{6}$/i.test(color||''); return <span className={cx('avatar', custom ? '' : color || 'green', size)} style={custom?{color,backgroundColor:`${color}18`}:undefined}>{children || <Icon size={size === 'large' ? 25 : 20} />}</span>; }
function Badge({ children, color = 'green' }) { return <span className={cx('badge', color)}>{children}</span>; }
function Empty({ icon: Icon = FolderOpen, title, text, action, actionLabel = '立即添加' }) { return <div className="empty-state"><div className="empty-icon"><Icon size={27} strokeWidth={1.6} /></div><h3>{title}</h3>{text && <p>{text}</p>}{action && <Button variant="secondary" icon={Plus} onClick={action}>{actionLabel}</Button>}</div>; }
function Field({ label, hint, children }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function TextContent({ children }) { return <div className="text-content">{String(children || '').split('\n').map((line, i) => line.startsWith('### ') ? <h4 key={i}>{line.slice(4)}</h4> : line.startsWith('## ') ? <h3 key={i}>{line.slice(3)}</h3> : line.startsWith('# ') ? <h3 key={i}>{line.slice(2)}</h3> : <p key={i}>{line.replace(/\*\*(.*?)\*\*/g, '$1') || '\u00a0'}</p>)}</div>; }
function SourceList({ sources, onOpen }) {
  const items = Array.isArray(sources) ? sources.filter((source, index, all) => source && typeof source.id === 'string' && typeof source.title === 'string' && all.findIndex(item => item?.id === source.id) === index) : [];
  if (!items.length) return null;
  return <details className="ai-sources"><summary><BookMarked size={14}/><span>本次参考资料</span><small>{items.length} 条</small><ChevronDown size={14}/></summary><p>提供给 AI 的个人资料，回答仍需核对。</p><ul>{items.map(source => {
    const deleted = source.deleted === true || source.availability === 'deleted';
    const label = deleted ? '附件已删除' : KINDS[source.kind]?.[0] || source.label || '个人记录';
    return <li key={source.id}>{onOpen && !deleted ? <button type="button" onClick={()=>onOpen(source)}><FileText size={14}/><span>{source.title}</span><small>{label}</small><ArrowUpRight size={13}/></button> : <span className="source-readonly"><FileText size={14}/><span>{source.title}</span><small>{label}</small></span>}</li>;
  })}</ul></details>;
}
function Modal({ title, subtitle, children, onClose, wide }) {
  useEffect(() => { const handler = e => e.key === 'Escape' && onClose(); document.addEventListener('keydown', handler); const original = document.body.style.overflow; document.body.style.overflow = 'hidden'; return () => { document.removeEventListener('keydown', handler); document.body.style.overflow = original; }; }, [onClose]);
  return <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && onClose()}><section className={cx('modal', wide && 'modal-wide')} role="dialog" aria-modal="true" aria-label={title}><header><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><IconButton icon={X} label="关闭" onClick={onClose} /></header>{children}</section></div>;
}
function Orbit({ compact }) { return <div className={cx('orbit', compact && 'compact')} aria-label="学习、生活、知识 AI 助手协作"><div className="orbit-ring ring-one" /><div className="orbit-ring ring-two" /><div className="orbit-core"><Sprout size={37} strokeWidth={1.5} /><small>你的成长</small></div><div className="orbit-agent orbit-a"><BookOpen size={20} /><span>学习规划</span></div><div className="orbit-agent orbit-b"><Heart size={20} /><span>健康生活</span></div><div className="orbit-agent orbit-c"><Sparkles size={20} /><span>灵感整理</span></div><div className="orbit-dot dot-one" /><div className="orbit-dot dot-two" /><div className="orbit-star"><Sparkles size={15} /></div></div>; }

export default function LifeOS({ initialView = 'user' }) {
  const [view, setView] = useState(initialView);
  const [recordKind, setRecordKind] = useState('');
  const [data, setData] = useState(EMPTY);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [toast, setToast] = useState(null);
  const [modal, setModal] = useState(null);
  const [sidebar, setSidebar] = useState(false);
  const [search, setSearch] = useState('');
  const [searchOpen, setSearchOpen] = useState(false);
  const toastTimer = useRef(null);
  const notify = useCallback((message, type = 'success') => { setToast({ message, type }); clearTimeout(toastTimer.current); toastTimer.current = setTimeout(() => setToast(null), 5000); }, []);
  const endSession = useCallback(() => { setData(EMPTY); setModal(null); setSidebar(false); window.location.replace('/login'); }, []);
  const navigate = useCallback((next, kind = '') => {
    if (next === 'admin') { window.location.assign('/admin'); return; }
    if (next === 'login') { window.location.assign('/login'); return; }
    const target = VIEWS[next] ? next : 'overview';
    setView(target); setRecordKind(kind); setSidebar(false);
    window.history.pushState({}, '', personalHref(target, kind));
    window.scrollTo({ top: 0, behavior: 'instant' });
  }, []);
  const refresh = useCallback(async () => { try { const result = await api(null, { resource: 'bootstrap' }); if (!result.user) { endSession(); return result; } const pages=new Set(); while(result.recordsNextCursor){const cursor=result.recordsNextCursor;if(pages.has(cursor))throw new Error('历史记录读取中断，请刷新重试');pages.add(cursor);const page=await api(null,{resource:'records',cursor});result.records.push(...page.records);result.recordsNextCursor=page.recordsNextCursor;}result.records=[...new Map(result.records.map(record=>[record.id,record])).values()]; setData({ ...EMPTY, ...result }); setLoadError(''); return result; } catch (e) { if (e.status === 401) endSession(); else setLoadError(e.message); } finally { setLoading(false); } }, [endSession]);
  useEffect(() => {
    const sync = () => {
      const query = new URLSearchParams(window.location.search);
      const path = window.location.pathname.replace(/\/$/, '');
      if (path !== '/user') { window.location.replace(path || '/'); return; }
      setView(personalView(query.get('view'))); setRecordKind(query.get('kind') || '');
    };
    sync(); window.addEventListener('popstate', sync); refresh();
    return () => { window.removeEventListener('popstate', sync); clearTimeout(toastTimer.current); };
  }, [refresh]);
  useEffect(() => {
    if (!data.user) return;
    let stopped = false, checking = false;
    const check = async () => {
      if (document.visibilityState === 'hidden' || checking) return;
      checking = true;
      try {
        const result = await api(null, { resource: 'session' });
        if (stopped) return;
        if (!result.user) endSession();
        else if (result.user.id !== data.user.id) window.location.reload();
      } catch {} finally { checking = false; }
    };
    window.addEventListener('focus', check); document.addEventListener('visibilitychange', check);
    const timer = setInterval(check, 60000);
    return () => { stopped = true; clearInterval(timer); window.removeEventListener('focus', check); document.removeEventListener('visibilitychange', check); };
  }, [data.user?.id, endSession]);
  const requireUser = useCallback((action) => { if (!data.user) { notify('登录后即可保存你的学习与生活记录。', 'info'); navigate('login'); return false; } action?.(); return true; }, [data.user, notify, navigate]);
  const perform = useCallback(async (payload, message, reload = true) => { try { const result = await api(payload); if (message) notify(message); if (reload) await refresh(); return result; } catch (e) { if (e.status === 401) endSession(); else notify(e.message, 'error'); throw e; } }, [notify, refresh, endSession]);
  const addRecord = (kind = 'task', record) => requireUser(() => setModal({ type: 'record', kind, record }));
  const checkout = (type, product) => requireUser(() => setModal({ type: 'checkout', productType: type, product }));
  const openSource = source => {
    if (source.deleted === true || source.availability === 'deleted') { notify('附件已删除，已保存的文字记录仍可查看。', 'info'); return; }
    if (['image','audio'].includes(source.kind)) {
      if (/^\/api\/media\?resource=asset&id=[0-9a-f-]{36}$/i.test(source.url || '')) window.open(source.url, '_blank', 'noopener,noreferrer');
      else notify('附件暂不可用。', 'info');
      return;
    }
    const record = data.records.find(item => item.id === source.id);
    const kind = record?.kind || source.kind;
    navigate(kind === 'note' ? 'knowledge' : ['habit','expense','health','event'].includes(kind) ? 'life' : 'learning', kind);
    if (record && KINDS[record.kind]) setModal({ type: 'record', kind: record.kind, record });
    else { setModal(null); notify('已打开对应模块；原记录可能已删除或不在当前列表。', 'info'); }
  };
  const openFocus = () => requireUser(() => setModal({ type: 'focus' }));
  const props = { data, navigate, notify, requireUser, perform, refresh, addRecord, checkout, setModal, openFocus, recordKind, openSource };
  const siteName = data.settings.siteName || '知序 LifeOS';
  const searchResults = search.trim() ? [...NAV.filter(n => n[1].includes(search)).map(n => ({ id: n[0], title: n[1], type: '功能', view: n[0] })), ...data.records.filter(r => `${r.title} ${r.content || ''}`.toLowerCase().includes(search.toLowerCase())).slice(0, 6).map(r => ({ ...r, type: KINDS[r.kind]?.[0] || '记录', view: r.kind === 'note' ? 'knowledge' : ['habit','expense','health','event'].includes(r.kind) ? 'life' : 'learning' }))] : [];
  if (loading || !data.user) return <main className="personal-gate">{loadError ? <><AlertCircle size={28} /><h1>暂时无法打开用户中心</h1><p role="alert">{loadError}</p><Button onClick={refresh}>重新连接</Button><a href="/">返回首页</a></> : <><Loader2 className="spin" size={28} /><p>正在打开你的用户中心…</p></>}</main>;
  return <div className="app-shell">
    {sidebar && <div className="sidebar-scrim" onClick={() => setSidebar(false)} />}
    <aside className={cx('sidebar', sidebar && 'is-open')}>
      <a className="brand" href="/user" onClick={e => { e.preventDefault(); navigate('user'); }}><span className="brand-symbol"><Sprout size={27} strokeWidth={2.1} /></span><span className="brand-name">{siteName}</span></a>
      <div className="workspace-switch"><span className="workspace-icon"><Home size={17} /></span><span>我的个人空间<small>学习与生活，从容有序</small></span><ChevronDown size={14} /></div>
      <div className="nav-label">工作空间</div>
      <nav aria-label="主导航">{NAV.map(([id, label, Icon], i) => <button key={id} onClick={() => navigate(id)} className={cx('nav-item', view === id && 'active', i === 6 && 'nav-separate')}><Icon size={19} strokeWidth={1.7} /><span>{label}</span>{id === 'agents' && <span className="nav-new">NEW</span>}{id === 'ai' && <span className="nav-dot" />}</button>)}</nav>
      <div className="sidebar-bottom"><div className="sidebar-tip"><div className="tip-symbol"><Sparkles size={19} /></div><strong>给成长，多一点可能</strong><p>解锁更多 AI 能力与专属插件</p><button onClick={() => navigate('membership')}>探索知序会员 <ArrowUpRight size={14} /></button></div><button className={cx('nav-item', view === 'user' && 'active')} onClick={() => navigate('user')}><Settings size={18} /><span>用户中心</span></button><div className="sidebar-profile" onClick={() => navigate(data.user ? 'user' : 'login')} role="button" tabIndex={0} onKeyDown={e => e.key === 'Enter' && navigate(data.user ? 'user' : 'login')}><span className="user-avatar">{data.user?.name?.slice(0,1) || <User size={19} />}</span><span><strong>{data.user?.name || '欢迎来到知序'}</strong><small>{data.user ? data.plans.find(p => p.id === data.user.planId)?.name || '免费账户' : '登录，开始你的成长旅程'}</small></span><ChevronRight size={15} /></div></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="mobile-menu icon-button" onClick={() => setSidebar(true)} aria-label="打开菜单"><Menu size={21} /></button><span className="breadcrumb-home">个人空间</span><ChevronRight className="breadcrumb-home" size={13} /><strong>{VIEWS[view]}</strong></div><div className="topbar-actions"><div className="search-box"><Search size={16} /><input aria-label="搜索功能、笔记" placeholder="搜索功能、笔记..." value={search} onChange={e => { setSearch(e.target.value); setSearchOpen(true); }} onFocus={() => setSearchOpen(true)} onBlur={() => setTimeout(() => setSearchOpen(false), 180)} /><kbd>⌕</kbd>{searchOpen && search && <div className="search-results">{searchResults.length ? searchResults.map(r => <button key={r.id} onMouseDown={e => e.preventDefault()} onClick={() => { navigate(r.view); setSearchOpen(false); setSearch(''); if (r.kind) setModal({ type: 'record', kind: r.kind, record: r }); }}><Search size={14} /><span>{r.title}</span><small>{r.type}</small></button>) : <p>没有找到相关内容，换个关键词试试。</p>}</div>}</div><IconButton icon={Bell} label="查看通知" onClick={() => setModal({ type: 'notice' })} /><div className="topbar-divider" />{data.user ? <button className="top-user" onClick={() => navigate('user')}><span className="user-avatar small">{data.user.name?.slice(0,1) || '知'}</span><span>{data.user.name}</span><ChevronDown size={13} /></button> : <Button className="login-top" variant="secondary" onClick={() => navigate('login')}>登录 / 注册</Button>}</div></header>
      <main className={cx('main-content', `view-${view}`)}>
        {loadError && <div className="error-banner"><AlertCircle size={18} /><span>{loadError}</span><button onClick={refresh}>重新连接</button></div>}
        {loading ? <div className="page-loading"><Loader2 className="spin" size={28} /><p>正在打开你的工作空间...</p></div> : <>
          {view === 'overview' && <Dashboard {...props} />}
          {view === 'ai' && <AIChat {...props} />}
          {view === 'media' && <MediaStudio {...props} initialMode={recordKind} />}
          {view === 'agents' && <AgentStudio {...props} />}
          {view === 'learning' && <RecordsPage {...props} mode="learning" />}
          {view === 'life' && <RecordsPage {...props} mode="life" />}
          {view === 'knowledge' && <Knowledge {...props} />}
          {view === 'plugins' && <PluginMarket {...props} />}
          {view === 'membership' && <Membership {...props} />}
          {view === 'user' && <UserCenter {...props} />}
        </>}
      </main><footer className="page-footer"><a className="footer-support" href="/"><Home size={13}/>网站首页</a><span>{siteName}，让每一天都在生长。</span><span>{data.settings.description||'为你的学习与生活而设计'} <Sprout size={12} /></span>{data.settings.supportContact&&<button className="footer-support" onClick={()=>setModal({type:'support'})}>联系支持<HelpCircle size={13}/></button>}</footer>
    </div>
    <nav className="mobile-bottom" aria-label="移动端导航">{[['overview','工作台',LayoutDashboard],['ai','AI 助手',Sparkles],['learning','学习',BookOpen],['life','生活',Leaf],['user','我的',User]].map(([id,label,Icon]) => <button key={id} className={view === id ? 'active' : ''} onClick={() => navigate(id)}><Icon size={21} strokeWidth={view === id ? 2.2 : 1.7} /><span>{label}</span></button>)}</nav>
    {toast && <div role="status" className={cx('toast', toast.type)}>{toast.type === 'error' ? <AlertCircle size={19} /> : toast.type === 'info' ? <Sparkles size={19} /> : <CheckCircle2 size={19} />}<span>{toast.message}</span><button aria-label="关闭提示" onClick={() => setToast(null)}><X size={15} /></button></div>}
    <FocusTimer {...props} open={modal?.type === 'focus'} onClose={() => setModal(null)} />
    {modal?.type === 'record' && <RecordModal key={`${modal.kind}:${modal.record?.id||'new'}`} {...props} kind={modal.kind} record={modal.record} onClose={() => setModal(null)} />}
    {modal?.type === 'checkout' && <CheckoutModal {...props} type={modal.productType} product={modal.product} onClose={() => setModal(null)} />}
    {modal?.type === 'support' && <Modal title="联系平台支持" onClose={() => setModal(null)}><div className="support-content"><HelpCircle size={25}/><TextContent>{data.settings.supportContact || '管理员尚未配置联系方式。请通过您获取本站地址时的联系渠道，向平台管理员说明注册邮箱及账户问题；请勿发送密码。'}</TextContent></div></Modal>}
    {modal?.type === 'notice' && <Modal title="通知与公告" onClose={() => setModal(null)}><div className="notice-content"><Avatar icon="sparkles" /><div><h3>欢迎使用{siteName}</h3><p>{data.settings.announcement || '从一个小目标开始，让 AI 助手陪你规划学习、记录生活、积累知识。'}</p></div></div>{data.orders.some(o => o.status === 'pending') && <div className="notice-content"><Avatar icon="wallet" color="orange" /><div><h3>你有待支付的订单</h3><p>前往用户中心查看付款方式与订单状态。</p><Button variant="text" onClick={() => { setModal(null); navigate('user'); }}>查看订单 <ArrowRight size={15} /></Button></div></div>}</Modal>}
  </div>;
}

function PageHeading({ title, description, children, eyebrow }) { return <div className="page-heading"><div>{eyebrow && <p className="heading-eyebrow">{eyebrow}</p>}<h1>{title}</h1>{description && <p>{description}</p>}</div>{children && <div className="heading-actions">{children}</div>}</div>; }
function SectionHeader({ title, description, action, onAction, children }) { return <div className="section-header"><div><h2>{title}</h2>{description && <p>{description}</p>}</div>{children || (action && <button className="text-link" onClick={onAction}>{action}<ChevronRight size={15} /></button>)}</div>; }

function Dashboard({ data, navigate, addRecord, perform, requireUser, notify, openFocus }) {
  const today = new Date();
  const dateLabel = today.toLocaleDateString('zh-CN', { month: 'long', day: 'numeric', weekday: 'long', timeZone: 'Asia/Shanghai' });
  const tasks = data.records.filter(r => r.kind === 'task' && r.status !== 'done' && r.status !== 'completed').slice(0,4);
  const completed = data.records.filter(r => r.kind === 'task' && ['done','completed'].includes(r.status)).length;
  const taskTotal = data.records.filter(r => r.kind === 'task').length;
  const habits = data.records.filter(r => r.kind === 'habit');
  const stats = [{ icon: BookOpen, label: '进行中的学习', value: data.records.filter(r => ['task','course','goal'].includes(r.kind) && !['done','completed'].includes(r.status)).length, unit: '项', color: 'green' }, { icon: Clock3, label: '累计专注时长', value: data.stats.focusMinutes || 0, unit: '分钟', color: 'purple' }, { icon: FileText, label: '我的知识笔记', value: data.stats.notes || data.records.filter(r => r.kind === 'note').length, unit: '篇', color: 'blue' }, { icon: Flame, label: '正在养成的习惯', value: habits.length, unit: '个', color: 'orange' }];
  return <><PageHeading title={data.user ? `${data.user.name}，今天也在向前。` : '每一天，都值得好好安排。'} description="把想做的事，变成正在发生的改变。"><div className="date-chip"><CalendarDays size={16} />{dateLabel}</div></PageHeading>
    <div className="dashboard-grid"><div className="dashboard-main"><section className="welcome-banner"><div className="welcome-copy"><div className="welcome-tag"><span />你的个人 AI 成长空间</div><h2>学习有方向，<br />生活有自己的节奏。</h2><p>{data.settings.description||<>让多位 AI 助手一起思考，<br className="mobile-br" />把你的目标拆解成每一天的小行动。</>}</p><div className="welcome-actions"><Button icon={Sparkles} onClick={() => navigate('agents')}>开启 AI 协作 <ArrowRight size={15} /></Button><button className="banner-secondary" onClick={() => addRecord('task')}>制定我的计划<ChevronRight size={15} /></button></div></div><Orbit /></section>
      <section className="stats-strip" aria-label="个人数据">{stats.map(s => <div key={s.label} className="stat-item"><span className={cx('stat-icon',s.color)}><s.icon size={18} /></span><p>{s.label}</p><strong>{data.user ? s.value : '—'}<small>{s.unit}</small></strong></div>)}</section>
      <section className="panel assistant-panel"><SectionHeader title="你的 AI 助手团队" description="各有所长，为同一个你。" action="查看全部" onAction={() => navigate('ai')} /><div className="assistant-grid">{data.agents.filter(a => a.enabled !== false).slice(0,4).map((agent,i) => <button className="assistant-card" key={agent.id} onClick={() => { window.sessionStorage.setItem('selectedAgent', agent.id); window.sessionStorage.removeItem(`zhixu-conversation-${data.user?.id||'guest'}`); navigate('ai'); }}><Avatar icon={agent.icon} color={['green','purple','orange','blue'][i % 4]} /><strong>{agent.name}</strong><p>{agent.description}</p><span>开始对话 <ArrowUpRight size={14} /></span></button>)}{!data.agents.length && <div className="inline-empty">助手团队正在准备中。管理员可在后台配置并启用 AI 助手。</div>}</div><div className="collaboration-strip"><span className="mini-orbit"><Workflow size={18} /></span><div><strong>复杂的目标，交给团队一起完成</strong><span>多 Agent 拆解、研究与整合，形成一份可执行的方案。</span></div><button onClick={() => navigate('agents')} aria-label="打开 Agent 工作室"><ArrowRight size={18} /></button></div></section>
      <div className="dashboard-lower"><section className="panel learning-panel"><SectionHeader title="学习进行时" action="全部计划" onAction={() => navigate('learning')} />{data.records.filter(r => ['goal','course'].includes(r.kind)).slice(0,2).map((r,i) => <button className="learning-item" key={r.id} onClick={() => addRecord(r.kind,r)}><Avatar icon={i ? 'target' : 'book'} color={i ? 'purple' : 'green'} /><div><h3>{r.title}</h3><p>{r.meta?.category || KINDS[r.kind]?.[0]}</p><div className="progress-track"><span style={{ width: `${Math.min(100,Number(r.meta?.progress)||0)}%` }} /></div></div><span className="progress-label">{Number(r.meta?.progress)||0}%</span></button>)}{!data.records.some(r => ['goal','course'].includes(r.kind)) && <div className="small-empty"><span className="empty-book"><BookOpen size={29} strokeWidth={1.4} /><Sprout size={20} /></span><div><h3>你的下一个成长，从这里开始</h3><p>一本书、一门课，或一个一直想实现的目标。</p><button className="text-link" onClick={() => addRecord('goal')}>添加学习目标 <Plus size={13} /></button></div></div>}</section><section className="panel habit-panel"><SectionHeader title="养成一个好习惯" action="管理习惯" onAction={() => navigate('life')} />{habits.length ? habits.slice(0,3).map(r => <button className="habit-row" key={r.id} onClick={async () => { const dates = r.meta?.checkedDates || []; const checked = dates.includes(dayKey()); try { await perform({ action: 'record.save', ...r, meta: { ...r.meta, checkedDates: checked ? dates.filter(d => d !== dayKey()) : [...dates,dayKey()] } }, checked ? '已取消今日打卡' : '今天又向前了一小步！'); } catch {} }}><span className="habit-icon"><Flame size={18} /></span><span>{r.title}<small>已打卡 {r.meta?.checkedDates?.length || 0} 天</small></span><span className={cx('habit-check',r.meta?.checkedDates?.includes(dayKey()) && 'checked')}><Check size={14} /></span></button>) : <div className="small-empty habit-empty"><div className="habit-demo"><span><Check size={13} /></span><span><Check size={13} /></span><span><Check size={13} /></span><span /><span /><span /><span /></div><h3>小小的坚持，也有大大的力量</h3><p>记录阅读、运动、早睡或你自己的好习惯。</p><button className="text-link" onClick={() => addRecord('habit')}>创建第一个习惯 <Plus size={13} /></button></div>}</section></div>
      <section className="quick-start"><span className="quick-label">随手记录</span>{[['note','写一条笔记',Pencil],['expense','记一笔收支',Wallet],['focus','开始专注',Clock3],['event','添加日程',CalendarDays]].map(([kind,label,Icon]) => <button key={kind} onClick={() => kind === 'focus' ? openFocus() : addRecord(kind)}><Icon size={16} />{label}<Plus size={13} /></button>)}</section>
    </div><aside className="dashboard-aside"><section className="panel daily-panel"><div className="daily-title"><h2>今天，慢慢来</h2><span>{today.toLocaleDateString('zh-CN',{month:'long',timeZone:'Asia/Shanghai'})}</span></div><div className="week-strip">{Array.from({length:7},(_,i) => { const d = new Date(today); d.setDate(today.getDate() - ((today.getDay()+6)%7) + i); const isToday = d.toDateString() === today.toDateString(); return <div key={i} className={isToday ? 'today' : ''}><span>{['一','二','三','四','五','六','日'][i]}</span><strong>{d.getDate()}</strong><i /></div>; })}</div><div className="daily-progress"><div className="progress-circle" style={{ '--progress': `${taskTotal ? completed/taskTotal*100 : 0}%` }}><span><strong>{completed}<small>/{taskTotal}</small></strong><em>任务完成</em></span></div><div><h3>{data.user ? '按自己的步调前进' : '从今天的一件小事开始'}</h3><p>{data.user ? '每完成一件事，离目标更近一点。' : '登录后，在这里看到你的真实进度。'}</p></div></div></section>
      <section className="panel today-tasks"><SectionHeader title="今日待办"><IconButton icon={Plus} label="添加待办" onClick={() => addRecord('task')} /></SectionHeader>{!data.user && <div className="example-label">灵感示例 · 登录后添加你的待办</div>}{(data.user ? tasks : EXAMPLE_TASKS).map((r,i) => <div className="todo-item" key={r.id || i}><button className="todo-check" aria-label={`完成 ${r.title}`} onClick={() => requireUser(async () => { try { await perform({ action: 'record.save', ...r, status: 'completed' }, '任务完成，做得好！'); } catch {} })}><Check size={12} /></button><div><button className="todo-title" onClick={() => r.id ? addRecord('task', r) : addRecord('task')}>{r.title}</button><div className="todo-meta"><span className={cx('tiny-tag',r.color || ['green','purple','orange'][i%3])}>{r.meta?.category || r.category || '学习任务'}</span>{r.meta?.dueDate && <small><Clock3 size={11} />{r.meta.dueDate.slice(5)}</small>}</div></div></div>)}{data.user && !tasks.length && <div className="no-tasks"><CheckCheck size={28} /><p>还没有待办事项</p><small>为今天安排一件值得完成的小事。</small></div>}<button className="add-task" onClick={() => addRecord('task')}><Plus size={15} />添加新任务</button></section>
      <section className="membership-teaser"><div className="teaser-top"><span><Crown size={19} /></span><Badge color="purple">知序会员</Badge></div><h3>给未来的自己，<br />多一份支持。</h3><p>更多 AI 协作额度，<br />更多让成长更轻松的工具。</p><button onClick={() => navigate('membership')}>了解会员权益<ArrowUpRight size={16} /></button><div className="teaser-decoration"><Sprout size={78} strokeWidth={1} /></div></section>
      <div className="aside-note"><Leaf size={16} /><p>不必一下子做到最好，<br />今天比昨天多走一步就好。</p></div>
    </aside></div></>;
}

function RecordModal({ kind, record, onClose, perform, data, openSource }) {
  const [busy,setBusy] = useState(false); const [error,setError] = useState('');
  async function save(e) { e.preventDefault(); setBusy(true); setError(''); const f = Object.fromEntries(new FormData(e.currentTarget)); const meta = {...record?.meta}; for(const key of ['dueDate','category','priority','amount','minutes','progress','direction','url','startTime','endTime','sleepHours','waterMl','exerciseMinutes','startDate','endDate','dailyMinutes','goalId','frequency']) if(f[key] !== undefined) meta[key] = ['amount','minutes','progress','sleepHours','waterMl','exerciseMinutes','dailyMinutes','frequency'].includes(key) ? Number(f[key]) : f[key]; try { await perform({action:'record.save',id:record?.id,kind,title:f.title,content:f.content || '',status:f.status || record?.status || 'active',meta},record ? '记录已更新' : '已添加到你的个人空间'); onClose(); } catch(e){setError(e.message);}finally{setBusy(false);} }
  async function remove() { if(!window.confirm(`确定删除“${record.title}”吗？删除后无法恢复。`)) return; setBusy(true); try { await perform({action:'record.delete',id:record.id},'记录已删除'); onClose(); }catch{}finally{setBusy(false);} }
  return <Modal title={`${record ? '编辑' : '添加'}${KINDS[kind]?.[0] || '记录'}`} subtitle="把每一个小行动，好好记录下来。" onClose={onClose} wide={kind === 'note' || kind === 'review'}><form onSubmit={save} className="modal-form"><Field label="标题"><input autoFocus name="title" required maxLength={160} defaultValue={record?.title || ''} placeholder={{task:'例如：完成英语听力练习',goal:'例如：三个月掌握 Python 基础',habit:'例如：每天阅读 20 分钟',expense:'例如：本周买菜',health:'例如：今日跑步 3 公里',event:'例如：周六下午的读书会',focus:'例如：专注学习高等数学',course:'例如：计算机科学导论',note:'给这篇笔记起个标题',review:'例如：本周学习复盘'}[kind]} /></Field><div className="form-columns"><Field label="分类"><input name="category" defaultValue={record?.meta?.category || ''} placeholder={kind === 'expense' ? '餐饮 / 交通 / 学习' : '为记录添加分类'} /></Field>{!['note','habit'].includes(kind) && <Field label={kind === 'event' ? '开始日期' : '记录 / 截止日期'}><input type="date" name="dueDate" defaultValue={record?.meta?.dueDate?.slice(0,10) || dayKey()} /></Field>}{kind === 'expense' && <><Field label="金额（元）"><input name="amount" type="number" step="0.01" min="0.01" required defaultValue={record?.meta?.amount || ''} placeholder="0.00"/></Field><Field label="收支类型"><select name="direction" defaultValue={record?.meta?.direction || 'expense'}><option value="expense">支出</option><option value="income">收入</option></select></Field></>}{kind === 'focus' && <Field label="专注时长（分钟）"><input name="minutes" type="number" min="1" max="1440" required defaultValue={record?.meta?.minutes || 25}/></Field>}{['task','goal','course'].includes(kind) && <><Field label="优先级"><select name="priority" defaultValue={record?.meta?.priority || 'normal'}><option value="low">低 · 慢慢来</option><option value="normal">普通</option><option value="high">高 · 优先完成</option></select></Field><Field label="状态"><select name="status" defaultValue={record?.status === 'done' ? 'completed' : record?.status || 'active'}><option value="active">进行中</option><option value="completed">已完成</option></select></Field>{kind !== 'task' && <Field label="学习进度（%）"><input name="progress" type="number" min="0" max="100" defaultValue={record?.meta?.progress || 0}/></Field>}</>}{kind === 'habit' && <Field label="目标频率（每周天数）" hint="设置每周计划打卡 1–7 天；每天最多记录一次打卡。"><input name="frequency" type="number" min="1" max="7" required defaultValue={record?.meta?.frequency || 7}/></Field>}{kind === 'task' && <Field label="关联学习目标"><select name="goalId" defaultValue={record?.meta?.goalId || ''}><option value="">不关联目标</option>{data.records.filter(r=>r.kind==='goal').map(g=><option key={g.id} value={g.id}>{g.title}</option>)}</select></Field>}{kind === 'course' && <Field label="课程链接"><input name="url" type="url" defaultValue={record?.meta?.url || ''} placeholder="https://..."/></Field>}{kind === 'event' && <><Field label="状态"><select name="status" defaultValue={record?.status === 'done' ? 'completed' : record?.status || 'active'}><option value="active">进行中</option><option value="completed">已完成</option></select></Field><Field label="结束日期" hint="跨天活动填写实际结束日期；留空视为当天。"><input type="date" name="endDate" defaultValue={record?.meta?.endDate || ''}/></Field><Field label="开始时间"><input type="time" name="startTime" defaultValue={record?.meta?.startTime || ''}/></Field><Field label="结束时间"><input type="time" name="endTime" defaultValue={record?.meta?.endTime || ''}/></Field></>}{kind === 'health' && <><Field label="睡眠（小时）"><input name="sleepHours" type="number" min="0" max="24" step="0.1" defaultValue={record?.meta?.sleepHours ?? ''}/></Field><Field label="饮水（毫升）"><input name="waterMl" type="number" min="0" max="20000" defaultValue={record?.meta?.waterMl ?? ''}/></Field><Field label="运动（分钟）"><input name="exerciseMinutes" type="number" min="0" max="1440" defaultValue={record?.meta?.exerciseMinutes ?? ''}/></Field></>}{kind === 'goal' && <><Field label="目标开始日期"><input type="date" name="startDate" defaultValue={record?.meta?.startDate || dayKey()}/></Field><Field label="目标结束日期"><input type="date" name="endDate" defaultValue={record?.meta?.endDate || ''}/></Field><Field label="每日投入（分钟）"><input name="dailyMinutes" type="number" min="0" max="1440" defaultValue={record?.meta?.dailyMinutes ?? 30}/></Field></>}</div><Field label={['note','review'].includes(kind) ? '正文内容' : '补充说明'}><textarea name="content" rows={['note','review'].includes(kind) ? 12 : 4} defaultValue={record?.content || ''} placeholder={kind === 'health' ? '记录睡眠、运动、饮食、身体感受等。AI 建议仅作日常参考。' : '写下想法、细节，或者下一步的行动...'} /></Field>{error && <div className="form-error">{error}</div>}<SourceList sources={record?.meta?.sources} onOpen={openSource}/><div className="modal-footer">{record && <Button type="button" variant="danger-text" icon={Trash2} onClick={remove} disabled={busy}>删除记录</Button>}<span className="spacer"/><Button type="button" variant="secondary" onClick={onClose}>取消</Button><Button loading={busy} type="submit" icon={Check}>保存记录</Button></div></form></Modal>;
}

function FocusTimer({ open, onClose, data, perform, notify, openFocus }) {
  const [phase,setPhase]=useState('focus');
  const [remaining,setRemaining]=useState(25*60);
  const [deadline,setDeadline]=useState(null);
  const [title,setTitle]=useState('我的专注时段');
  const [saving,setSaving]=useState(false);
  const [error,setError]=useState('');
  const completing=useRef(false);
  const sessionRequest=useRef(null);
  const total=phase==='focus'?25*60:5*60;
  const elapsed=total-remaining;
  useEffect(()=>{setDeadline(null);setRemaining(25*60);setPhase('focus');setError('');sessionRequest.current=null;},[data.user?.id]);
  useEffect(()=>{
    if(!deadline)return;
    const tick=()=>setRemaining(Math.max(0,Math.ceil((deadline-Date.now())/1000)));
    tick();const timer=setInterval(tick,250);
    return()=>clearInterval(timer);
  },[deadline]);
  const finish=useCallback(async()=>{
    if(completing.current)return;
    completing.current=true;setDeadline(null);setSaving(true);setError('');
    try{
      sessionRequest.current ||= requestUUID();
      await perform({action:'record.save',requestId:sessionRequest.current,kind:'focus',title:title.trim()||'我的专注时段',status:'completed',content:'番茄钟专注记录',meta:{minutes:Math.max(1,Math.round((25*60-remaining)/60)),seconds:25*60-remaining,dueDate:dayKey(),category:'番茄钟'}},'专注已记录，休息一下吧');
      setPhase('break');setRemaining(5*60);
    }catch(e){setError(e.message);}
    finally{completing.current=false;setSaving(false);}
  },[perform,remaining,title]);
  useEffect(()=>{
    if(deadline&&remaining===0){
      if(phase==='focus')finish();
      else{setDeadline(null);setPhase('focus');setRemaining(25*60);sessionRequest.current=null;notify('休息结束，可以开始下一段专注了。');}
    }
  },[deadline,remaining,phase,finish,notify]);
  function changePhase(next){sessionRequest.current=null;setDeadline(null);setPhase(next);setRemaining(next==='focus'?25*60:5*60);setError('');}
  if(!open)return deadline?<button className="focus-floating" onClick={openFocus}><Timer size={17}/>{String(Math.floor(remaining/60)).padStart(2,'0')}:{String(remaining%60).padStart(2,'0')}</button>:null;
  return <Modal title="专注番茄钟" subtitle="一次只做一件事，让注意力回到眼前。" onClose={onClose}><div className="focus-timer"><div className="focus-phase-tabs"><button className={phase==='focus'?'active':''} disabled={saving} onClick={()=>changePhase('focus')}>专注 25 分钟</button><button className={phase==='break'?'active':''} disabled={saving} onClick={()=>changePhase('break')}>休息 5 分钟</button></div><div className="focus-clock" style={{'--progress':`${elapsed/total*100}%`}}><div><strong role="timer" aria-label={`剩余 ${Math.floor(remaining/60)} 分 ${remaining%60} 秒`}>{String(Math.floor(remaining/60)).padStart(2,'0')}:{String(remaining%60).padStart(2,'0')}</strong><span>{phase==='focus'?'认真投入，慢慢向前':'让大脑喘口气'}</span></div></div>{phase==='focus'&&<Field label="这段时间，你想专注什么？"><input value={title} onChange={e=>setTitle(e.target.value)} maxLength={160} placeholder="例如：阅读一章专业书"/></Field>}<div className="focus-actions"><Button variant="secondary" icon={RefreshCw} disabled={saving} onClick={()=>changePhase(phase)}>重置</Button><Button icon={deadline?Pause:Play} disabled={saving||remaining===0} onClick={()=>{if(deadline)setDeadline(null);else{if(phase==='focus')sessionRequest.current ||= requestUUID();setDeadline(Date.now()+remaining*1000);}}}>{deadline?'暂停':'开始'}</Button>{phase==='focus'&&<Button variant="secondary" icon={Check} loading={saving} disabled={elapsed<1} onClick={finish}>完成并保存</Button>}</div>{error&&<div className="form-error">{error} 点击“完成并保存”重试。</div>}<p className="focus-tip">关闭窗口后计时继续；刷新网页将重置未完成时段。完成的专注会自动保存到学习记录。</p></div></Modal>;
}

function RecordsPage({ mode, data, addRecord, perform, navigate, requireUser, recordKind, openFocus }) {
  const kinds = mode === 'learning' ? ['task','goal','course','focus','review'] : ['habit','expense','health','event'];
  const [kind,setKind] = useState(kinds[0]); const [filter,setFilter] = useState('all'); const [query,setQuery] = useState('');
  useEffect(() => {setKind((mode === 'learning' ? ['task','goal','course','focus','review'] : ['habit','expense','health','event']).includes(recordKind) ? recordKind : mode === 'learning' ? 'task' : 'habit');setFilter('all');},[mode,recordKind]);
  const list = data.records.filter(r => r.kind === kind && (filter === 'all' || (filter === 'done' ? ['done','completed'].includes(r.status) : !['done','completed'].includes(r.status))) && `${r.title} ${r.content||''}`.toLowerCase().includes(query.toLowerCase()));
  const expenses = data.records.filter(r=>r.kind==='expense'); const totalExpense = expenses.filter(r=>r.meta?.direction!=='income').reduce((a,r)=>a+Number(r.meta?.amount||0),0);const totalIncome=expenses.filter(r=>r.meta?.direction==='income').reduce((a,r)=>a+Number(r.meta?.amount||0),0);
  const toggleHabit = async r => {const dates=r.meta?.checkedDates||[];const checked=dates.includes(dayKey());try{await perform({action:'record.save',...r,meta:{...r.meta,checkedDates:checked?dates.filter(d=>d!==dayKey()):[...dates,dayKey()]}},checked?'已取消今日打卡':'打卡成功，继续保持！');}catch{}};
  return <><PageHeading title={mode==='learning'?'让每一份努力，都有方向。':'认真生活，也照顾自己。'} description={mode==='learning'?'从目标到行动，记录学习的每一次积累。':'习惯、收支、健康与日程，在这里找到舒服的节奏。'}><Button variant="secondary" icon={Sparkles} onClick={()=>navigate('ai')}>让 AI 帮我规划</Button><Button icon={Plus} onClick={()=>addRecord(kind)}>添加{KINDS[kind][0]}</Button></PageHeading>{kind==='focus'&&<section className="focus-invitation"><span className="summary-icon green"><Timer size={25}/></span><div><h2>给自己一段不被打扰的时间。</h2><p>专注 25 分钟，休息 5 分钟。完成后自动记入你的专注记录。</p></div><Button icon={Play} onClick={openFocus}>打开番茄钟</Button></section>}{kind==='expense'&&<div className="balance-banner"><span>账本结余</span><strong>¥ {currency(totalIncome-totalExpense)}</strong><small>累计收入 ¥ {currency(totalIncome)} − 累计支出 ¥ {currency(totalExpense)}</small></div>}<div className="record-summary">{(mode==='learning'?[['学习任务',data.records.filter(r=>r.kind==='task').length,ListChecks],['已完成任务',data.records.filter(r=>r.kind==='task'&&['done','completed'].includes(r.status)).length,CheckCircle2],['专注分钟',data.stats.focusMinutes||0,Clock3],['学习目标',data.records.filter(r=>r.kind==='goal').length,Target]]:[['正在养成的习惯',data.records.filter(r=>r.kind==='habit').length,Flame],['今日已打卡',data.records.filter(r=>r.kind==='habit'&&r.meta?.checkedDates?.includes(dayKey())).length,CheckCircle2],['累计支出',`¥ ${currency(totalExpense)}`,Wallet],['累计收入',`¥ ${currency(totalIncome)}`,TrendingUp]]).map(([label,value,Icon],i)=><div key={label}><span className={cx('summary-icon',['green','purple','blue','orange'][i])}><Icon size={20}/></span><span><small>{label}</small><strong>{data.user?value:'—'}</strong></span></div>)}</div><section className="panel records-panel"><div className="tab-bar">{kinds.map(k=>{const Icon=KINDS[k][1];return <button key={k} className={kind===k?'active':''} onClick={()=>{setKind(k);setFilter('all');}}><Icon size={17}/>{KINDS[k][0]}<span>{data.records.filter(r=>r.kind===k).length}</span></button>;})}</div><div className="records-toolbar"><div className="filter-pills" aria-label={kind==='event'?'日程状态筛选':undefined}>{['all','active','done'].map((f,i)=><button key={f} onClick={()=>setFilter(f)} aria-pressed={filter===f} className={filter===f?'active':''}>{['全部','进行中','已完成'][i]}</button>)}</div><div className="local-search"><Search size={16}/><input aria-label="搜索记录" placeholder="搜索记录..." value={query} onChange={e=>setQuery(e.target.value)}/></div></div>{list.length?<div className={kind==='habit'?'habit-grid':'record-list'}>{list.map(r=>kind==='habit'?<div className="habit-card" key={r.id}><div className="habit-card-top"><Avatar icon="leaf" color="green"/><IconButton icon={MoreHorizontal} label="编辑习惯" onClick={()=>addRecord(kind,r)}/></div><h3>{r.title}</h3><p>{r.content || '每天为自己积累一点改变'}</p><div className="habit-week">{Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=d.toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});return <span key={i} className={r.meta?.checkedDates?.includes(key)?'done':''} title={key}>{r.meta?.checkedDates?.includes(key)?<Check size={14}/>:d.getDate()}</span>;})}</div><div className="habit-card-bottom"><small>每周 {r.meta?.frequency||7} 天 · 累计 {r.meta?.checkedDates?.length||0} 天</small><Button variant={r.meta?.checkedDates?.includes(dayKey())?'secondary':'primary'} icon={Check} onClick={()=>toggleHabit(r)}>{r.meta?.checkedDates?.includes(dayKey())?'今日已打卡':'今日打卡'}</Button></div></div>:<div key={r.id} className="record-row">{['task','event'].includes(kind)?<button className={cx('record-checkbox',['done','completed'].includes(r.status)&&'checked')} aria-pressed={['done','completed'].includes(r.status)} aria-label={kind==='event'?`${['done','completed'].includes(r.status)?'恢复':'完成'}日程 ${r.title}`:`切换 ${r.title} 完成状态`} onClick={async()=>{try{await perform({action:'record.save',...r,status:['done','completed'].includes(r.status)?'active':'completed'},kind==='event'?['done','completed'].includes(r.status)?'日程已恢复为进行中':'日程已完成':'任务状态已更新');}catch{}}}><Check size={15}/></button>:<Avatar icon={kind==='expense'?'wallet':kind==='health'?'heart':kind==='event'?'calendar':kind==='focus'?'target':'book'} color={kind==='expense'?'orange':'green'}/>}<button className="record-main" onClick={()=>addRecord(kind,r)}><h3 className={['done','completed'].includes(r.status)?'completed-text':''}>{r.title}</h3><p>{r.content?.slice(0,90)||r.meta?.category||KINDS[kind][0]}</p>{kind==='event'&&(r.meta?.startTime||r.meta?.endTime)&&<div className="record-metrics"><Clock3 size={13}/>{r.meta.dueDate||'未设日期'} {r.meta.startTime||''} — {r.meta.endDate||r.meta.dueDate||''} {r.meta.endTime||''}</div>}{kind==='health'&&<div className="record-metrics">{r.meta?.sleepHours!=null&&<span>睡眠 {r.meta.sleepHours} 小时</span>}{r.meta?.waterMl!=null&&<span>饮水 {r.meta.waterMl} ml</span>}{r.meta?.exerciseMinutes!=null&&<span>运动 {r.meta.exerciseMinutes} 分钟</span>}</div>}{['goal','course'].includes(kind)&&<div className="record-progress"><div className="progress-track"><span style={{width:`${Math.min(100,Number(r.meta?.progress)||0)}%`}}/></div><small>{r.meta?.progress||0}%</small></div>}</button><div className="record-detail">{kind==='expense'?<strong className={r.meta?.direction==='income'?'income':'expense'}>{r.meta?.direction==='income'?'+':'−'} ¥{currency(r.meta?.amount)}</strong>:kind==='focus'?<strong>{r.meta?.minutes||0} <small>分钟</small></strong>:<Badge color={['done','completed'].includes(r.status)?'green':'gray'}>{statusName(r.status)}</Badge>}{r.meta?.dueDate&&<small><CalendarDays size={12}/>{r.meta.dueDate}</small>}</div><div className="record-actions">{kind==='course'&&/^https?:\/\//i.test(r.meta?.url||'')&&<a className="icon-button" href={r.meta.url} target="_blank" rel="noopener noreferrer" aria-label={`打开课程 ${r.title}`} title="打开课程资源"><ExternalLink size={17}/></a>}<IconButton icon={Pencil} label="编辑记录" onClick={()=>addRecord(kind,r)}/></div></div>)}</div>:<Empty icon={KINDS[kind][1]} title={query?'没有找到匹配的记录':`还没有${KINDS[kind][0]}`} text={query?'试试其他关键词。':`添加第一条${KINDS[kind][0]}，把你的成长留在这里。`} action={()=>addRecord(kind)}/>}</section></>;
}

function Knowledge({data,addRecord,navigate}) {
  const [q,setQ]=useState('');const [category,setCategory]=useState('全部笔记');const notes=data.records.filter(r=>r.kind==='note');const categories=['全部笔记',...new Set(notes.map(r=>r.meta?.category).filter(Boolean))];const list=notes.filter(r=>(category==='全部笔记'||r.meta?.category===category)&&`${r.title} ${r.content}`.toLowerCase().includes(q.toLowerCase()));
  return <><PageHeading title="让好想法，有一个归处。" description="收藏、整理、连接，把零散的信息变成自己的知识。"><Button variant="secondary" icon={Sparkles} onClick={()=>navigate('ai')}>与 AI 一起整理</Button><Button icon={Plus} onClick={()=>addRecord('note')}>写一篇笔记</Button></PageHeading><div className="knowledge-layout"><aside className="panel knowledge-folders"><h3>我的知识空间</h3>{categories.map((c,i)=><button key={c} className={category===c?'active':''} onClick={()=>setCategory(c)}>{i===0?<BookMarked size={17}/>:<FolderOpen size={17}/>}<span>{c}</span><small>{i===0?notes.length:notes.filter(r=>r.meta?.category===c).length}</small></button>)}<div className="knowledge-tip"><Sprout size={25}/><p>知识的价值，<br/>在于被重新想起。</p></div></aside><div><div className="knowledge-toolbar"><h2>{category} <small>{list.length} 篇</small></h2><div className="local-search"><Search size={16}/><input placeholder="搜索笔记内容..." aria-label="搜索笔记" value={q} onChange={e=>setQ(e.target.value)}/></div></div>{list.length?<div className="note-grid">{list.map((r,i)=><button className="note-card" key={r.id} onClick={()=>addRecord('note',r)}><div className="note-card-top"><Avatar icon="knowledge" color={['green','purple','blue','orange'][i%4]}/><ArrowUpRight size={17}/></div>{r.meta?.category&&<span className="note-category">{r.meta.category}</span>}<h3>{r.title}</h3><p>{r.content||'点击编辑，为这篇笔记添加内容。'}</p><footer><span>{fmtDate(r.updatedAt||r.createdAt)}</span><span>{r.content?.length||0} 字</span></footer></button>)}</div>:<section className="panel"><Empty icon={BookMarked} title={q?'没有找到这条笔记':'为值得记住的事，留一页空间'} text="读过的书、学到的方法、突然出现的灵感，都可以成为你的知识。" action={()=>addRecord('note')} actionLabel="写下第一篇笔记"/></section>}</div></div></>;
}

function AIChat({ data, requireUser, perform, notify, navigate, refresh, openSource }) {
  const agents=data.agents.filter(a=>a.enabled!==false); const [selected,setSelected]=useState('');const [messages,setMessages]=useState([]);const [input,setInput]=useState('');const [busy,setBusy]=useState(false);const [conversationId,setConversationId]=useState(null); const [historyLoading,setHistoryLoading]=useState(false); const bottom=useRef(null); const historyKey=`zhixu-conversation-${data.user?.id||'guest'}`;
  useEffect(()=>{const saved=window.sessionStorage.getItem('selectedAgent');setSelected(agents.find(a=>a.id===saved)?.id||agents[0]?.id||'');},[]);
  useEffect(()=>{const saved=window.sessionStorage.getItem(historyKey);if(saved&&data.conversations?.some(c=>c.id===saved))loadConversation(saved);},[data.user?.id]);
  function newConversation(agentId=selected){setSelected(agentId);window.sessionStorage.setItem('selectedAgent',agentId);setMessages([]);setConversationId(null);window.sessionStorage.removeItem(historyKey);}
  async function loadConversation(id){if(busy||historyLoading)return;setHistoryLoading(true);try{const r=await api(null,{resource:'conversation',id});setSelected(r.conversation.agentId);setMessages(r.conversation.messages||[]);setConversationId(r.conversation.id);window.sessionStorage.setItem(historyKey,r.conversation.id);}catch(e){notify(e.message,'error');window.sessionStorage.removeItem(historyKey);}finally{setHistoryLoading(false);}}
  useEffect(()=>{ bottom.current?.scrollIntoView({behavior:'smooth',block:'nearest'}); },[messages,busy]);
  const agent=agents.find(a=>a.id===selected)||agents[0];
  async function send(e,prompt){e?.preventDefault();const message=(prompt||input).trim();if(!message||busy||historyLoading||!requireUser())return;setInput('');setMessages(prev=>[...prev,{role:'user',content:message}]);setBusy(true);try{const r=await perform({action:'ai.chat',message,agentId:agent?.id,conversationId},null,false);setConversationId(r.conversationId);window.sessionStorage.setItem(historyKey,r.conversationId);setMessages(prev=>[...prev,{role:'assistant',content:r.reply,sources:r.sources}]);await refresh();}catch(e){setMessages(prev=>[...prev,{role:'error',content:e.message}]);}finally{setBusy(false);}}
  return <><PageHeading title="一个好问题，是改变的开始。" description="和你的专属 AI 助手聊聊，把想法变成清晰的下一步。"><Button variant="secondary" icon={Mic} onClick={()=>navigate('media')}>语音与拍照</Button><Button variant="secondary" icon={Workflow} onClick={()=>navigate('agents')}>让多位 Agent 协作</Button></PageHeading><div className="chat-layout"><aside className="panel chat-sidebar"><div className="chat-sidebar-title"><h3>选择你的助手</h3><span>{agents.length} 位</span></div><div className="chat-agent-options">{agents.map((a,i)=><button key={a.id} className={cx('chat-agent',selected===a.id&&'active')} disabled={busy||historyLoading} onClick={()=>newConversation(a.id)}><Avatar icon={a.icon} color={['green','purple','orange','blue'][i%4]}/><span><strong>{a.name}</strong><small>{a.role}</small></span>{selected===a.id&&<span className="online-dot"/>}</button>)}</div><details className="conversation-history"><summary><MessageCircle size={15}/>历史对话 <span>{data.conversations?.length||0}</span><ChevronDown size={14}/></summary>{data.conversations?.length?data.conversations.map(c=><button key={c.id} className={conversationId===c.id?'active':''} disabled={busy||historyLoading} onClick={()=>loadConversation(c.id)}><MessageCircle size={14}/><span>{c.title}</span><small>{fmtDate(c.updated_at)}</small></button>):<p>发送第一条消息后，对话会保存在这里。</p>}</details><div className="chat-sidebar-note"><ShieldCheck size={17}/><p>你的对话只在个人账户内保存。AI 回答可能存在偏差，请结合实际情况判断。</p></div></aside><section className="panel chat-panel"><header className="chat-header"><Avatar icon={agent?.icon}/><div><strong>{agent?.name||'知序 AI 助手'}</strong><span><i/>{busy?'正在认真思考...':'准备好，陪你一起向前'}</span></div><Button variant="text" icon={Plus} disabled={busy||historyLoading} onClick={()=>newConversation()}>新对话</Button></header><div className="chat-messages">{historyLoading?<div className="page-loading"><Loader2 size={24} className="spin"/><p>正在打开历史对话...</p></div>:messages.length?messages.map((m,i)=><div key={i} className={cx('message',m.role)}>{m.role!=='user'&&<Avatar icon={agent?.icon}/>}<div className="message-bubble">{m.role==='error'?<><AlertCircle size={17}/><p>{m.content}</p><button onClick={()=>setInput(messages[i-1]?.content||'')}>将问题放回输入框</button></>:<><TextContent>{m.content}</TextContent>{m.role==='assistant'&&<SourceList sources={m.sources} onOpen={openSource}/>}</>}</div>{m.role==='user'&&<span className="user-avatar">{data.user?.name?.slice(0,1)||'我'}</span>}</div>):<div className="chat-welcome"><div className="chat-welcome-mark"><Sparkles size={32} strokeWidth={1.5}/></div><h2>你好，我是{agent?.name||'你的 AI 助手'}</h2><p>{agent?.description||'一起梳理目标，找到适合你的成长路径。'}</p><div className="prompt-grid">{['帮我制定一份适合上班族的英语学习计划','我想养成早睡和运动的习惯，从哪里开始？','帮我整理本周的目标，安排学习和休息','怎样建立自己的知识体系，让学过的知识用起来？'].map((p,i)=><button key={p} onClick={()=>send(null,p)}><span>{[<BookOpen size={18}/>,<Leaf size={18}/>,<CalendarDays size={18}/>,<BookMarked size={18}/>][i]}</span>{p}<ArrowUpRight size={15}/></button>)}</div></div>}{busy&&<div className="message assistant"><Avatar icon={agent?.icon}/><div className="thinking"><span/><span/><span/><small>正在组织思路</small></div></div>}<div ref={bottom}/></div><form className="chat-composer" onSubmit={send}><textarea rows={2} aria-label="发送给 AI 的消息" placeholder={`向${agent?.name||'AI 助手'}提问，或说说你现在的想法...`} value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send(e);}}}/><div><span>Enter 发送，Shift + Enter 换行</span><Button type="submit" loading={busy} disabled={!input.trim()||historyLoading} icon={Send}>发送</Button></div></form><p className="ai-disclaimer">AI 内容仅供参考；健康与财务相关决策请咨询专业人士。</p></section></div></>;
}

function AgentStudio({data,perform,requireUser,notify,refresh,navigate,openSource}) {
  const agents=data.agents.filter(a=>a.enabled!==false&&!['planner','reviewer'].includes(a.id));const [selected,setSelected]=useState(()=>{const defaults=['study','life','wellness'].filter(id=>agents.some(a=>a.id===id));return defaults.length?defaults:agents.slice(0,3).map(a=>a.id);});const [goal,setGoal]=useState('');const [busy,setBusy]=useState(false);const [run,setRun]=useState(()=>data.runs?.find(r=>['queued','running'].includes(r.status))||null);const [pollError,setPollError]=useState('');
  useEffect(()=>{if(!run?.id||!['queued','running','pending'].includes(run.status))return;let alive=true;const tick=async()=>{try{const r=await api(null,{resource:'run',id:run.id});if(alive){setRun(r.run);setPollError('');if(!['queued','running','pending'].includes(r.run.status))refresh();}}catch(e){if(alive)setPollError(e.message);}};const timer=setInterval(tick,2500);tick();return()=>{alive=false;clearInterval(timer);};},[run?.id,run?.status,refresh]);
  async function start(e){e.preventDefault();if(!requireUser())return;if(!selected.length){notify('请至少选择一位协作助手。','info');return;}setBusy(true);try{const r=await perform({action:'ai.run',goal,agentIds:selected},'协作任务已开始',false);setRun({id:r.runId,goal,status:'queued',steps:[]});await refresh();}catch{}finally{setBusy(false);}}
  return <><PageHeading title="一个目标，一支 AI 团队。" description="让不同专长的 Agent 依次思考、交换成果，形成完整的行动方案。"><Badge color="purple"><Workflow size={13}/>多 Agent 协作</Badge></PageHeading><div className="studio-layout"><section className="panel studio-input"><div className="studio-heading"><span className="studio-icon"><Workflow size={25}/></span><div><h2>你想一起完成什么？</h2><p>说清楚目标、时间与现状，团队会给出更贴合你的方案。</p></div></div><form onSubmit={start}><textarea className="goal-input" rows={5} value={goal} onChange={e=>setGoal(e.target.value)} required minLength={5} maxLength={6000} placeholder="例如：我是一名工作两年的产品经理，希望在 3 个月内学会 Python 数据分析。每天有 1 小时学习时间，还想保持每周 3 次运动。请帮我制定兼顾学习和生活的可执行计划。"/><div className="studio-presets">{['30 天英语口语提升计划','兼顾工作与运动的每周安排','从零开始建立个人知识库'].map(g=><button key={g} type="button" onClick={()=>setGoal(g)}><Sparkles size={12}/>{g}</button>)}</div><div className="studio-agent-heading"><h3>选择协作成员</h3><span>已选 {selected.length} / 3 位专家</span></div><div className="studio-agents">{agents.map((a,i)=><button type="button" key={a.id} className={cx('studio-agent',selected.includes(a.id)&&'selected')} disabled={!selected.includes(a.id)&&selected.length>=3} onClick={()=>setSelected(s=>s.includes(a.id)?s.filter(x=>x!==a.id):s.length<3?[...s,a.id]:s)}><Avatar icon={a.icon} color={['green','purple','orange','blue'][i%4]}/><span><strong>{a.name}</strong><small>{a.role}</small></span><span className="selection-check">{selected.includes(a.id)&&<Check size={12}/>}</span></button>)}</div><div className="studio-submit"><p><ShieldCheck size={14}/>规划师拆解 → 1–3 位专家 → 复盘顾问汇总；每次 5 额度</p><Button type="submit" loading={busy} disabled={!goal.trim()||['queued','running','pending'].includes(run?.status)} icon={Play}>启动协作任务</Button></div></form></section><aside className="panel studio-history"><SectionHeader title="协作记录"/><div className="run-list">{data.runs?.length?data.runs.slice(0,15).map(r=><button key={r.id} className={cx(run?.id===r.id&&'active')} onClick={async()=>{try{const result=await api(null,{resource:'run',id:r.id});setRun(result.run);}catch(e){notify(e.message,'error');}}}><div><Workflow size={17}/><Badge color={r.status==='completed'?'green':r.status==='failed'?'red':'purple'}>{statusName(r.status)}</Badge></div><h4>{r.goal}</h4><small>{fmtDate(r.createdAt,true)}</small></button>):<div className="history-empty"><Workflow size={28}/><p>第一场协作，<br/>从你的一个想法开始。</p></div>}</div></aside></div>{run&&<section className="panel run-detail"><SectionHeader title={run.status==='completed'?'团队协作已完成':run.status==='partial'?'协作部分完成':run.status==='failed'?'协作任务未完成':'团队正在协作'} description={run.goal}>{<Badge color={run.status==='failed'?'red':run.status==='completed'?'green':'purple'}>{['queued','pending','running'].includes(run.status)&&<Loader2 size={12} className="spin"/>}{statusName(run.status)}</Badge>}</SectionHeader>{pollError&&<div className="form-error">{pollError} 正在尝试重新连接。</div>}<div className="run-steps">{run.steps?.length?run.steps.map((s,i)=><div className={cx('run-step',s.status)} key={s.id||i}><div className="run-step-icon">{s.status==='completed'?<Check size={18}/>:s.status==='running'?<Loader2 size={18} className="spin"/>:s.status==='failed'?<AlertCircle size={18}/>:<Bot size={18}/>}</div><div className="run-step-body"><div><h3>{s.name||s.role||`协作成员 ${i+1}`}</h3><span>{statusName(s.status)}{s.latency?` · ${(s.latency/1000).toFixed(1)}s`:''}</span></div>{s.content&&<details open={s.status==='running'}><summary>查看思考成果</summary><TextContent>{s.content}</TextContent><SourceList sources={s.sources} onOpen={openSource}/></details>}{s.error&&<p className="form-error">{s.error}</p>}</div></div>):<div className="run-starting"><Loader2 size={20} className="spin"/><p>正在组织你的 AI 团队，任务将在后台持续运行。</p></div>}</div>{run.result&&<div className="run-result"><div><h3><Sparkles size={19}/>{run.status==='partial'?'已完成部分的协作方案':'团队协作方案'}</h3><Button variant="secondary" icon={BookMarked} onClick={async()=>{try{await perform({action:'run.save',id:run.id},'协作方案已保存到知识库');}catch{}}}>保存到知识库</Button></div><TextContent>{run.result}</TextContent><SourceList sources={run.sources||run.steps?.[run.steps.length-1]?.sources} onOpen={openSource}/></div>}{run.error&&<div className="form-error">{run.error}</div>}</section>}</>;
}

function PluginMarket({data,perform,requireUser,checkout,notify,openFocus,navigate,refresh,openSource}) {
  const [category,setCategory]=useState('全部插件');const [query,setQuery]=useState('');const [busy,setBusy]=useState('');const [using,setUsing]=useState(null);const [message,setMessage]=useState('');const [reply,setReply]=useState('');const [sources,setSources]=useState([]);
  const owned=p=>(data.ownedPluginIds||[]).includes(p.id)||data.orders.some(o=>o.type==='plugin'&&o.productId===p.id&&o.status==='paid');
  const categories=['全部插件','已安装','已购',...new Set(data.plugins.filter(p=>p.enabled!==false&&p.listed!==false).map(p=>p.category).filter(Boolean))];const plugins=data.plugins.filter(p=>(category==='已安装'?data.installed.includes(p.id):category==='已购'?owned(p):p.enabled!==false&&p.listed!==false&&(category==='全部插件'||p.category===category))&&`${p.name} ${p.description}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>Number(a.sortOrder||0)-Number(b.sortOrder||0));
  async function install(p){if(!requireUser())return;setBusy(p.id);try{await api({action:'plugin.install',pluginId:p.id});await refresh();notify('插件已安装，可以开始使用了');}catch(e){if(e.status===402)checkout('plugin',p);else notify(e.message,'error');}finally{setBusy('');}}
  async function use(e){e.preventDefault();setBusy('run');try{const r=await perform({action:'plugin.run',pluginId:using.id,message},'结果已生成并保存到知识库');setReply(r.reply);setSources(r.sources||[]);}catch{}finally{setBusy('');}}
  return <><PageHeading title="给你的成长，添一件好工具。" description="按需安装学习与生活插件，让工作空间更适合你。"><Badge color="green"><Puzzle size={13}/>已安装 {data.installed.length} 个插件</Badge></PageHeading><section className="plugin-feature"><div><span className="feature-label"><Puzzle size={15}/>知序插件集</span><h2>小工具，帮你把日子过得更好。</h2><p>学习规划、阅读整理、健康管理，从需要的那一件开始。</p></div><div className="puzzle-art"><span><BookOpen size={30}/></span><span><Heart size={30}/></span><span><Puzzle size={30}/></span><span><Sparkles size={30}/></span></div></section><div className="market-toolbar"><div className="filter-pills">{categories.map(c=><button key={c} className={category===c?'active':''} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="local-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="找一个需要的工具..." aria-label="搜索插件"/></div></div>{plugins.length?<div className="plugin-grid">{plugins.map((p,i)=>{const installed=data.installed.includes(p.id);return <article className="panel plugin-card" key={p.id}><div className="plugin-card-top"><Avatar icon={p.icon} color={['green','purple','orange','blue'][i%4]} size="large"/><div className="plugin-availability"><Badge color={Number(p.price)>0?'purple':'green'}>{Number(p.price)>0?'付费插件':'免费插件'}</Badge>{p.enabled===false?<Badge color="red">服务已暂停</Badge>:p.listed===false&&<Badge color="gray">已下架 · 权益保留</Badge>}</div></div><div className="plugin-title"><h3>{p.name}</h3>{installed&&<CheckCircle2 size={15}/>}</div><span className="plugin-category">{p.category||'效率工具'}</span><p>{p.description}</p><div className="plugin-features">{(Array.isArray(p.features)?p.features:[]).slice(0,3).map(f=><span key={f}><Check size={12}/>{f}</span>)}</div><footer><strong>{Number(p.price)>0?<>¥ {currency(p.price)}<small>一次购买</small></>:'免费使用'}</strong>{installed?<div className="plugin-installed-actions"><Button variant="text" loading={busy===p.id} onClick={async()=>{setBusy(p.id);try{await perform({action:'plugin.uninstall',pluginId:p.id},'插件已卸载');}catch{}finally{setBusy('');}}}>卸载</Button><Button icon={Play} disabled={p.enabled===false} onClick={()=>{if(p.id==='focus'){openFocus();return;}if(p.id==='habit'){navigate('life','habit');return;}setUsing(p);setMessage('');setReply('');setSources([]);}}>{p.enabled===false?'暂停运行':'使用'}</Button></div>:<Button variant={Number(p.price)>0?'secondary':'primary'} icon={Plus} loading={busy===p.id} disabled={p.enabled===false} onClick={()=>install(p)}>{p.enabled===false?'暂停服务':owned(p)?'重新安装':Number(p.price)>0?'购买安装':'免费安装'}</Button>}</footer></article>;})}</div>:<Empty icon={Puzzle} title="没有找到这个插件" text="试试其他分类或搜索词。"/>}{using&&<Modal title={using.name} subtitle={using.description} onClose={()=>setUsing(null)} wide><form className="modal-form" onSubmit={use}><Field label="告诉插件，你希望完成什么"><textarea rows={4} required minLength={2} value={message} onChange={e=>setMessage(e.target.value)} placeholder={`例如：${using.category?.includes('健康')?'帮我制定一周的健康饮食计划':'根据我的目标，给我一个详细、可以执行的方案'}`}/></Field><Button type="submit" loading={busy==='run'} icon={Sparkles}>运行插件</Button>{reply&&<div className="plugin-result"><Badge color="green"><Check size={12}/>结果已保存到知识库</Badge><TextContent>{reply}</TextContent><SourceList sources={sources} onOpen={openSource}/></div>}</form></Modal>}</>;
}

function Membership({data,checkout,navigate}) {
  return <><div className="membership-heading"><span className="membership-symbol"><Crown size={28} strokeWidth={1.5}/></span><h1>为持续成长，留一点空间。</h1><p>选择适合你的方案，让 AI 陪你走得更远。</p><div className="membership-billing"><CheckCircle2 size={14}/>透明定价，按需选择，权益随账户生效</div></div><div className="plan-grid">{data.plans.filter(p=>p.enabled!==false).map((p,i)=><article key={p.id} className={cx('plan-card',i===1&&'featured')}>{i===1&&<div className="plan-recommended"><Sparkles size={13}/>适合持续成长的你</div>}<div className="plan-icon">{i===0?<Sprout size={24}/>:i===1?<Crown size={24}/>:<Zap size={24}/>}</div><h2>{p.name}</h2><p className="plan-description">{p.description||['从记录和规划开始，建立自己的成长节奏','更多 AI 支持，给学习与生活加一点动力','充足的协作能力，认真对待每一个目标'][i%3]}</p><div className="plan-price"><span>¥</span><strong>{currency(p.price)}</strong><small>{Number(p.price)===0?'/ 免费':`/ ${p.days||30} 天`}</small></div><Button variant={i===1?'primary':'secondary'} className="full-width" onClick={()=>Number(p.price)===0?navigate(data.user?'user':'login'):checkout('membership',p)}>{data.user?.planId===p.id?'续费当前方案':Number(p.price)===0?(data.user?'当前账户权益':'免费开始'):'选择此方案'}<ArrowRight size={15}/></Button><div className="plan-features"><strong>包含以下权益</strong>{(Array.isArray(p.features)?p.features:[]).map(f=><p key={f}><Check size={15}/>{f}</p>)}<p><Check size={15}/>{p.credits||0} AI 使用额度</p></div></article>)}</div><section className="membership-faq"><h2>关于你的会员</h2>{[['购买后如何生效？','在线支付成功并由服务端确认后，会员权益会自动发放；线下支付需要管理员核对订单后确认。'],['免费用户可以使用哪些功能？','免费账户可以管理个人学习与生活记录、安装免费插件，并按账户额度使用 AI 助手。具体权益以所选方案为准。'],['付费插件和会员有什么区别？','会员提供账户权益与 AI 额度；付费插件按管理员设置的价格单独购买，购买后可在插件市场安装使用。']].map(([q,a])=><details key={q}><summary>{q}<Plus size={16}/></summary><p>{a}</p></details>)}</section></>;
}

function CheckoutModal({type,product,data,perform,onClose,navigate}) {
  const payment=data.settings.payment||{};const [method,setMethod]=useState(payment.epayEnabled?'epay':payment.manualEnabled?'manual':payment.stripeEnabled?'stripe':'');const [channel,setChannel]=useState('alipay');const [busy,setBusy]=useState(false);const [created,setCreated]=useState(null);const [error,setError]=useState('');
  const orderRequest=useRef({id:requestUUID(),key:''});
  async function create(){const key=JSON.stringify([type,product.id,method,method==='epay'?channel:'']);if(orderRequest.current.key&&orderRequest.current.key!==key)orderRequest.current.id=requestUUID();orderRequest.current.key=key;setBusy(true);setError('');try{const r=await perform({action:'order.create',type,productId:product.id,paymentMethod:method,channel,requestId:orderRequest.current.id},'订单已创建');setCreated(r);if(r.paymentUrl)window.open(r.paymentUrl,'_blank','noopener,noreferrer');}catch(e){setError(e.message);}finally{setBusy(false);}}
  return <Modal title={created?'订单已创建':'确认你的订单'} subtitle={type==='membership'?'为下一段成长，准备更多支持。':'一件适合你的工具，随时待命。'} onClose={onClose}><div className="checkout-body"><div className="checkout-product"><Avatar icon={type==='membership'?'sparkles':product.icon} color="purple" size="large"/><div><h3>{product.name}</h3><p>{type==='membership'?`${product.days||30} 天会员权益`:'插件使用权 · 一次购买'}</p></div><strong>¥ {currency(product.price)}</strong></div>{!created?<><h3 className="form-section-title">选择支付方式</h3><div className="payment-methods">{payment.epayEnabled&&[['alipay','支付宝',Wallet],['wxpay','微信支付',MessageCircle]].map(([value,label,Icon])=><button key={value} className={method==='epay'&&channel===value?'active':''} onClick={()=>{setMethod('epay');setChannel(value);}}><Icon size={21}/><span><strong>{label}</strong><small>安全收银台，支付后自动开通</small></span><span className="radio-dot"/></button>)}{payment.manualEnabled&&<button className={method==='manual'?'active':''} onClick={()=>setMethod('manual')}><CreditCard size={21}/><span><strong>线下转账</strong><small>提交订单，由管理员核对开通</small></span><span className="radio-dot"/></button>}{payment.stripeEnabled&&<button className={method==='stripe'?'active':''} onClick={()=>setMethod('stripe')}><CreditCard size={21}/><span><strong>银行卡支付</strong><small>Stripe 安全支付</small></span><span className="radio-dot"/></button>}</div>{!method&&<div className="form-error">当前未开放支付通道，请联系管理员。</div>}{error&&<div className="form-error">{error}</div>}<div className="checkout-total"><span>实付金额</span><strong>¥ {currency(product.price)}</strong></div><Button className="full-width" loading={busy} disabled={!method} onClick={create} icon={LockKeyhole}>创建订单并支付</Button><p className="checkout-note">权益在支付完成并确认后生效。</p></>:<div className="order-created"><CheckCircle2 size={37}/><h3>订单已准备好</h3><p className="order-number">订单编号：{created.order?.id}</p>{created.paymentUrl?<><p>请在收银台完成支付。支付成功后回到用户中心查看权益。</p><a className="btn btn-primary" href={created.paymentUrl} target="_blank" rel="noreferrer">打开支付收银台<ExternalLink size={15}/></a></>:<div className="manual-instructions"><h4>付款说明</h4><p>{payment.manualInstructions||'请联系管理员获取收款方式，并提供此订单编号。管理员核对到账后会为你开通权益。'}</p></div>}<Button variant="secondary" className="full-width" onClick={()=>{onClose();navigate('user');}}>前往用户中心查看订单</Button></div>}</div></Modal>;
}

function UserCenter({data,navigate,perform,notify,requireUser,refresh,openFocus}) {
  const [tab,setTab]=useState('overview');const [busy,setBusy]=useState(false);const plan=data.plans.find(p=>p.id===data.user?.planId);const apk=data.settings.apk||{};
  async function saveProfile(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));setBusy(true);try{await perform({action:'profile.update',...f},'个人信息已更新');e.target.reset();}catch{}finally{setBusy(false);}}
  const entries=[...NAV.filter(n=>n[0]!=='overview'),...Object.entries(KINDS).map(([id,[label,Icon]])=>[id,id==='focus'?'专注番茄钟':label,Icon]),['voice','实时语音对话',Mic],['image','拍照与图片助手',Camera],['recording','录音与转写',AudioLines],['apk','安卓客户端下载',Smartphone],['export','导出我的数据',Download]];
  const entryGroups=[['学习成长',['learning','task','goal','course','focus','review','knowledge','note']],['生活管理',['life','habit','expense','health','event']],['AI 与效率',['ai','voice','image','recording','agents','plugins']],['账户与应用',['membership','apk','export']]];
  const renderEntries=(guest=false)=><div className="feature-entry-groups">{entryGroups.map(([label,ids])=><section className="feature-entry-group" key={label}><h3>{label}</h3><div className="feature-entry-grid">{ids.map(id=>{const entry=entries.find(item=>item[0]===id);if(!entry)return null;const [,name,Icon]=entry;return <button key={id} onClick={()=>guest&&['export','focus'].includes(id)?navigate('login'):openEntry(id)}><span><Icon size={21}/></span><strong>{name}</strong><ChevronRight size={15}/></button>;})}</div></section>)}</div>;
  function openEntry(id){if(['voice','image','recording'].includes(id)){navigate('media',id);return;}if(id==='apk'){setTab('apk');return;}if(id==='export'){window.open('/api/app?resource=export','_blank','noopener,noreferrer');return;}if(id==='focus'){openFocus();return;}if(KINDS[id]){navigate(id==='note'?'knowledge':['habit','expense','health','event'].includes(id)?'life':'learning',id);return;}navigate(id);}
  if(!data.user)return tab==='apk'?<><PageHeading title="安卓客户端下载" description="手机安装后，可登录同一账户继续学习与生活记录。"><Button variant="secondary" icon={ArrowLeft} onClick={()=>setTab('overview')}>返回全部功能</Button></PageHeading><APKDownload data={data}/></>:<><PageHeading title="你的每一次成长，都值得被记住。" description="登录账户，拥有你的学习与生活空间。"/><section className="panel guest-center"><span className="guest-center-symbol"><User size={34}/></span><h2>欢迎来到你的个人中心</h2><p>你的学习计划、知识库、AI 团队和成长记录，都在这里。</p><Button onClick={()=>navigate('login')} icon={ArrowRight}>登录 / 注册账户</Button></section><section className="panel user-features"><SectionHeader title="一个账户，连接所有成长工具"/>{renderEntries(true)}</section></>;
  return <><PageHeading title="我的个人中心" description="账户、权益与每一份成长记录，都在这里。"><Button variant="secondary" icon={LogOut} onClick={async()=>{try{await perform({action:'auth.logout'},'已退出登录');navigate('login');}catch{}}}>退出登录</Button></PageHeading><section className="profile-banner"><span className="profile-avatar">{data.user.name?.slice(0,1)}</span><div><h2>{data.user.name}<Badge color="green">{plan?.name||'免费账户'}</Badge></h2><p>{data.user.email}</p><small>{fmtDate(data.user.createdAt)} 加入知序</small></div><div className="profile-credits"><span>可用 AI 额度</span><strong>{data.user.credits??0}</strong></div><Button variant="secondary" icon={Crown} onClick={()=>navigate('membership')}>升级会员</Button></section><div className="user-tabs tab-bar">{[['overview','全部功能'],['profile','个人资料与安全'],['orders','我的订单'],['apk','安卓客户端']].map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div>{tab==='overview'&&<><section className="panel user-features"><SectionHeader title="我的全部功能" description="从这里快速回到你想做的事。"/>{renderEntries()}</section><section className="panel account-membership"><div><Crown size={25}/><span><h3>我的会员权益</h3><p>{plan?.name||'免费账户'}{data.user.planExpires?` · 有效期至 ${fmtDate(data.user.planExpires)}`:' · 开启你的成长旅程'}</p></span></div><Button variant="secondary" onClick={()=>navigate('membership')}>查看会员方案<ArrowRight size={15}/></Button></section></>}{tab==='profile'&&<section className="panel profile-form"><SectionHeader title="个人资料与账户安全" description="修改密码时，需要验证当前密码。"/><form onSubmit={saveProfile}><Field label="你的称呼"><input name="name" required defaultValue={data.user.name} minLength={2} maxLength={30}/></Field><Field label="邮箱地址"><input disabled value={data.user.email}/></Field><div className="form-divider"/><h3>修改登录密码</h3><Field label="当前密码"><input type="password" name="currentPassword" autoComplete="current-password" placeholder="不修改密码时留空"/></Field><Field label="新密码"><input type="password" name="password" autoComplete="new-password" minLength={8} placeholder="至少 8 位，建议包含字母与数字"/></Field><Button loading={busy} type="submit" icon={Check}>保存修改</Button></form></section>}{tab==='orders'&&<section className="panel"><SectionHeader title="我的订单"><Button variant="text" icon={RefreshCw} onClick={refresh}>刷新状态</Button></SectionHeader>{data.orders.length?<div className="table-wrap"><table><thead><tr><th>商品</th><th>金额</th><th>支付方式</th><th>状态</th><th>创建时间</th></tr></thead><tbody>{data.orders.map(o=><tr key={o.id}><td><strong>{o.title}</strong><small className="table-sub">{o.id}</small></td><td>¥ {currency(o.amount)}</td><td>{{manual:'线下转账',epay:'支付宝 / 微信',stripe:'银行卡'}[o.paymentMethod]||o.paymentMethod}</td><td><Badge color={o.status==='paid'?'green':'orange'}>{statusName(o.status)}</Badge></td><td>{fmtDate(o.createdAt,true)}</td></tr>)}</tbody></table></div>:<Empty icon={Receipt} title="还没有订单" text="购买会员或付费插件后，可在这里查看支付与权益状态。"/>}</section>}{tab==='apk'&&<APKDownload data={data}/>}</>;
}

function APKDownload({data}) {
  const configured=data.settings.apk||{};const apk=configured.published||configured;
  return <section className="panel apk-download"><div className="phone-mockup"><span/><div className="phone-logo"><Sprout size={38}/><strong>{data.settings.siteName||'知序 LifeOS'}</strong><small>学习与生活</small></div><div className="phone-lines"><i/><i/><i/></div><div className="phone-bottom"><Home size={12}/><Sparkles size={12}/><BookOpen size={12}/><User size={12}/></div></div><div><Badge color="green"><Smartphone size={12}/>Android 客户端</Badge><h2>把成长，放进口袋。</h2><p>学习计划、AI 助手与生活记录，随时随地陪伴你。</p><div className="apk-metadata"><span>应用名称<strong>{apk.appName||'知序 LifeOS'}</strong></span><span>当前版本<strong>{apk.versionName||'1.0.0'}</strong></span><span>平台<strong>Android 6.0+</strong></span>{apk.size>0&&<span>安装包大小<strong>{fileSize(apk.size)}</strong></span>}{apk.builtAt&&<span>构建时间<strong>{fmtDate(apk.builtAt,true)}</strong></span>}</div>{apk.downloadUrl?<a className="btn btn-primary" href={apk.downloadUrl} download><Download size={17}/>下载安卓 APK</a>:<div className="inline-empty">客户端正在准备中，管理员完成构建后即可下载。</div>}<p className="apk-note">适用于 Android 6.0 及以上。客户端以 WebView 打开本站，需要联网；数据与你的网页账户同步。下载后按安卓系统提示安装。</p></div></section>;
}
